"use client";

import React, { useState, useRef } from "react";
import { motion } from "motion/react";
import { Sun, SunDim, SunMedium } from "lucide-react";
import { cn } from "@/lib/utils";

export interface IosSliderProps
  extends React.HTMLAttributes<HTMLDivElement> {
  defaultValue?: number;
  min?: number;
  max?: number;
  onValueChange?: (value: number) => void;
}

export function IosSlider({
  defaultValue = 65,
  min = 0,
  max = 100,
  onValueChange,
  className,
  ...props
}: IosSliderProps) {
  const [value, setValue] = useState(defaultValue);
  const [isDragging, setIsDragging] = useState(false);
  const trackRef = useRef<HTMLDivElement>(null);

  const updateFromPointer = (clientY: number) => {
    if (!trackRef.current) return;
    const rect = trackRef.current.getBoundingClientRect();
    const relativeY = clientY - rect.top;
    const percentage = 1 - Math.max(0, Math.min(1, relativeY / rect.height));
    const newValue = Math.round(min + percentage * (max - min));
    setValue(newValue);
    onValueChange?.(newValue);
  };

  const handlePointerDown = (e: React.PointerEvent<HTMLDivElement>) => {
    setIsDragging(true);
    (e.target as HTMLElement).setPointerCapture(e.pointerId);
    updateFromPointer(e.clientY);
  };

  const handlePointerMove = (e: React.PointerEvent<HTMLDivElement>) => {
    if (!isDragging) return;
    updateFromPointer(e.clientY);
  };

  const handlePointerUp = (e: React.PointerEvent<HTMLDivElement>) => {
    setIsDragging(false);
    try {
      (e.target as HTMLElement).releasePointerCapture(e.pointerId);
    } catch {
      // ignore
    }
  };

  const fillHeight = `${((value - min) / (max - min)) * 100}%`;

  return (
    <div
      data-slot="ios-slider"
      className={cn(
        "flex flex-col items-center justify-center gap-4 select-none p-6",
        className
      )}
      {...props}
    >
      <div
        ref={trackRef}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerCancel={handlePointerUp}
        className={cn(
          "relative h-64 w-20 cursor-ns-resize overflow-hidden rounded-[32px] border border-white/20 bg-neutral-200/80 dark:bg-neutral-800/80 shadow-2xl backdrop-blur-xl transition-transform duration-200",
          isDragging ? "scale-[1.04]" : "scale-100"
        )}
      >
        {/* Filled active track level */}
        <motion.div
          style={{ height: fillHeight }}
          transition={{ type: "spring", stiffness: 450, damping: 30 }}
          className="absolute bottom-0 left-0 right-0 bg-white dark:bg-neutral-100 shadow-md"
        />

        {/* Icon at Bottom */}
        <div className="absolute bottom-5 left-0 right-0 flex items-center justify-center pointer-events-none z-10 text-neutral-800 dark:text-neutral-900 mix-blend-difference invert dark:invert-0">
          {value < 30 ? (
            <SunDim className="h-6 w-6" />
          ) : value < 70 ? (
            <SunMedium className="h-6 w-6" />
          ) : (
            <Sun className="h-6 w-6" />
          )}
        </div>
      </div>

      <div className="flex flex-col items-center gap-1">
        <span className="font-mono text-xs font-bold text-neutral-800 dark:text-neutral-200">
          {value}%
        </span>
        <span className="text-[11px] text-muted-foreground font-mono">
          Display Brightness
        </span>
      </div>
    </div>
  );
}
